ga03(){return"\u0417\u0430\u043f\u0430\u0437\u0438 \u0441\u044a\u0449\u0435\u0441\u0442\u0432\u0443\u0432\u0430\u0449\u0430\u0442\u0430"},
ga02(){return"\u041f\u0440\u043e\u043f\u0443\u0441\u043d\u0438 \u0432\u043d\u0435\u0441\u0435\u043d\u0438\u0442\u0435 \u0431\u0435\u043b\u0435\u0436\u043a\u0438, \u043a\u043e\u0438\u0442\u043e \u0432\u0435\u0447\u0435 \u0441\u044a\u0449\u0435\u0441\u0442\u0432\u0443\u0432\u0430\u0442 \u043b\u043e\u043a\u0430\u043b\u043d\u043e"},
a0i(a){return"\u041f\u0430\u0440\u043e\u043b\u0430\u0442\u0430 \u0442\u0440\u044f\u0431\u0432\u0430 \u0434\u0430 \u0441\u044a\u0434\u044a\u0440\u0436\u0430 \u043f\u043e\u043d\u0435 "+a+" \u0441\u0438\u043c\u0432\u043e\u043b\u0430"},
ga0e(){return"\u0411\u0435\u0437 \u043f\u0430\u0440\u043e\u043b\u0430 \u0431\u0435\u043b\u0435\u0436\u043a\u0438\u0442\u0435 \u0449\u0435 \u0431\u044a\u0434\u0430\u0442 \u0438\u0437\u043d\u0435\u0441\u0435\u043d\u0438 \u0432 \u043e\u0442\u0432\u043e\u0440\u0435\u043d \u0432\u0438\u0434 \u0438 \u0432\u0441\u0435\u043a\u0438, \u043f\u043e\u043b\u0443\u0447\u0438\u043b \u0444\u0430\u0439\u043b\u0430, \u0449\u0435 \u043c\u043e\u0436\u0435 \u0434\u0430 \u0433\u0438 \u043f\u0440\u043e\u0447\u0435\u0442\u0435."},
ga2o(){return"\u041e\u0447\u0430\u043a\u0432\u0430 \u0441\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0430\u0446\u0438\u044f"},
ga2n(){return"\u0422\u0430\u0437\u0438 \u0431\u0435\u043b\u0435\u0436\u043a\u0430 \u0432\u0441\u0435 \u043e\u0449\u0435 \u043d\u0435 \u0435 \u0441\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0438\u0440\u0430\u043d\u0430 \u0441 \u043c\u0440\u0435\u0436\u0430\u0442\u0430"},
